/**
 * True if all servers use OAuth2 as authentication method and no password
 * entry is required.
 *
 * @returns {boolean}
 */
isOauthOnly() {
  return (
    this.incoming.auth === Ci.nsMsgAuthMethod.OAuth2 &&
    (this.configureOutgoingFromIncoming() ||
      this.outgoing.auth === Ci.nsMsgAuthMethod.OAuth2)
  );
},
